const trig = $('When Called').first().json;
const resp = $input.first().json || {};
const tags = Array.isArray(resp.tags) ? resp.tags : [];
const firstTag = tags.length ? String(tags[0]) : null;
const tags_pg = firstTag === null ? '{}' : '{"' + firstTag.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"}';
return [{ json: { ...trig, tags, observed_tag: firstTag, tags_pg } }];

const ctx = $('Extract Tags').first().json;
const row = $input.first().json || {};
return [{ json: {
  conversation_id: ctx.conversation_id || null,
  opportunity_id: ctx.opportunity_id || null,
  property_public_id: ctx.property_public_id || null,
  tags: ctx.tags,
  observed_tag: row.observed_tag || ctx.observed_tag || null,
  resolved: row.resolved === true,
  reason: row.reason || 'missing_owner_data',
  failure_detail: row.failure_detail || null,
  owner_agent_id: row.owner_agent_id || null,
  owner_name: row.owner_name || null,
  owner_number: row.owner_number || null
} }];

const input = $input.first().json;
const code = String(input.property_public_id || '').trim().toUpperCase();
return [{ json: { ...input, property_public_id: code, valid_eb_code: /^EB-[A-Z0-9]{4,}$/.test(code) } }];
